define(["jquery","core/str"],function($,Str){const loadCss=url=>{if(!url||document.querySelector("link[data-videoprogress-datatables]")){return}const link=document.createElement("link");link.rel="stylesheet";link.href=url;link.dataset.videoprogressDatatables="1";document.head.appendChild(link)};const loadScript=url=>new Promise(resolve=>{if($.fn.DataTable||!url){resolve();return}const script=document.createElement("script");script.src=url;script.onload=resolve;script.onerror=resolve;document.head.appendChild(script)});const init=()=>{document.querySelectorAll('[data-region="report"]').forEach(root=>{let config={};try{config=JSON.parse(root.dataset.datatableConfig||"{}")}catch(error){config={}}loadCss(config.cssurl);Promise.all([loadScript(config.jsurl),Str.get_strings([{key:"datatableempty",component:"videoprogress"},{key:"datatableloading",component:"videoprogress"}])]).then(values=>{if(!$.fn.DataTable){return}$(root).find('[data-region="students-table"]').DataTable({paging:false,searching:false,info:false,order:[],autoWidth:false,language:{emptyTable:values[1][0],loadingRecords:values[1][1]}})})})};return{init:init}});